#include "resident/domains/military/military_model.hpp"
#include "political_governance_continuation_declarations.hpp"
#include "political_governance_continuation.hpp"
#include <algorithm>
namespace hanmo::resident {
// 只容作者同一接任Office、辖区原钱包和一个原粮库；支出额度仍由原责任及热门专项Grant双验。
bool governance_continuation_grant_declares_resource(const CommonCatalog& common,const OrganizationCatalog& org,const PoliticsCatalog& politics,const MilitaryCatalog& military,const PoliticalTakeoverCatalog& takeover,bool enabled,const StableId& id,const ResourceKey& resource){
 if(!enabled||!takeover.enabled||!validate_political_takeover_catalog(common,org,politics,military,takeover).ok||(resource.kind!=ResourceKey::Kind::wallet&&resource.kind!=ResourceKey::Kind::inventory))return false;const auto* g=org.grants.find(id);if(!g||g->allowed_command_kinds!=std::vector<StableId>{political_governance_continue_command}||g->wallet_ids.size()!=1||g->inventory_ids.size()!=1||g->scopes.size()!=1||g->scopes.front().kind!=ScopeRef::Kind::site||g->amount_limit<1||(g->continuity_policy_id!="continue_under_organization"&&g->continuity_policy_id!="stop_when_vacant"))return false;const auto* office=org.offices.find(g->office_id);if(!office||std::find(office->grant_ids.begin(),office->grant_ids.end(),id)==office->grant_ids.end())return false;
 for(const auto& row:takeover.rules.rows()){const auto& r=row.second;const auto* j=politics.jurisdictions.find(r.jurisdiction_id);if(!j||r.successor_office_id!=office->id||r.site_id!=g->scopes.front().id||g->wallet_ids.front()!=j->public_wallet_id||std::find(j->public_inventory_ids.begin(),j->public_inventory_ids.end(),g->inventory_ids.front())==j->public_inventory_ids.end())continue;const auto h=std::find_if(military.strongholds.begin(),military.strongholds.end(),[&](const auto& value){return value.id==r.stronghold_id;});if(h==military.strongholds.end()||std::find(h->public_wallet_ids.begin(),h->public_wallet_ids.end(),g->wallet_ids.front())==h->public_wallet_ids.end()||std::find(h->public_inventory_ids.begin(),h->public_inventory_ids.end(),g->inventory_ids.front())==h->public_inventory_ids.end())continue;const auto& selected=resource.kind==ResourceKey::Kind::wallet?g->wallet_ids:g->inventory_ids;if(std::find(selected.begin(),selected.end(),resource.id)==selected.end())continue;const auto* definition=resource.kind==ResourceKey::Kind::wallet?common.required_wallets.find(resource.id):common.required_inventories.find(resource.id);if(definition&&definition->owner.kind==Owner::Kind::organization&&org.organizations.find(definition->owner.id))return true;}
 return false;
}
}
